@Component({
  selector: 'app-plan-list',
  imports: [RouterLink],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './plan-list.html',
})
export class PlanList {
  readonly country = input.required<Country>();
  readonly complete = output<void>();
  protected readonly store = inject(PlanState);
  private readonly injector = inject(Injector);
  private readonly heading = viewChild.required<ElementRef<HTMLElement>>('heading');
  private retryHadFocus = false;
  protected readonly view = computed(() => {
    const state = this.store.view();
    return state.phase !== 'idle' && state.country === this.country()
      ? state
      : { phase: 'loading' as const };
  });
  protected readonly selected = computed(() => this.store.selected(this.country()));
  protected readonly countryLabel = computed(() =>
    this.country() === 'co' ? 'Colombia' : 'Chile',
  );
  protected readonly status = computed(() => {
    const state = this.view();
    switch (state.phase) {
      case 'loading':
      case 'retrying':
        return 'Cargando los planes…';
      case 'checking':
        return 'Verificando tu plan…';
      case 'unavailable':
        return 'No pudimos cargar los planes. Intenta de nuevo.';
      case 'ready':
        if (state.lostChoice)
          return state.plans.length
            ? 'Tu plan cambió o ya no está disponible. Selecciona un plan para continuar.'
            : 'Tu plan cambió o ya no está disponible.';
        if (!state.plans.length) return 'No hay planes disponibles.';
        return state.recovered ? 'Planes disponibles.' : '';
    }
  });

  constructor() {
    effect(() => {
      this.country();
      this.focusHeading();
    });

    effect(() => {
      const state = this.view();
      if (state.phase === 'retrying') return;
      if (state.phase === 'ready' && state.recovered && this.retryHadFocus) {
        afterNextRender(
          () => {
            const focused = document.activeElement;
            if (focused === document.body) this.heading().nativeElement.focus();
          },
          { injector: this.injector },
        );
      }
      this.retryHadFocus = false;
    });
  }

  protected retry(event: MouseEvent) {
    if (this.view().phase !== 'unavailable') return;
    this.retryHadFocus = document.activeElement === event.currentTarget;
    this.store.read(this.country(), 'retrying');
  }

  protected proceed() {
    if (!this.selected()) return;
    this.heading().nativeElement.focus();
    this.complete.emit();
  }

  protected displayPrice(price: PlanPrice) {
    const scale = price.currency === 'COP' ? 100 : 1;
    return priceFormat[price.currency].format(price.amountMinor / scale);
  }

  private focusHeading() {
    afterNextRender(() => this.heading().nativeElement.focus(), { injector: this.injector });
  }
}
import { HttpClient } from '@angular/common/http';
import { inject, Injectable, signal } from '@angular/core';
import {
  decodePlanCatalog,
  decodePlanPrice,
  isPlanId,
  isRecord,
  type Country,
  type Plan,
  type PlanPrice,
} from '@quote/contract';
import type { Subscription } from 'rxjs';

type Candidate = { id: string; price: PlanPrice };
type ReadMode = 'loading' | 'retrying' | 'checking';

export type PlanView =
  | { phase: 'idle' }
  | { phase: ReadMode | 'unavailable'; country: Country }
  | {
      phase: 'ready';
      country: Country;
      plans: readonly Plan[];
      lostChoice: boolean;
      checkedForSummary: boolean;
      recovered: boolean;
    };

function candidateKey(country: Country) {
  return `quote-plan-v1:${country}`;
}

function restoreCandidate(country: Country): Candidate | null {
  try {
    const text = sessionStorage.getItem(candidateKey(country));
    if (!text || text.length > 512) return null;
    const value: unknown = JSON.parse(text);
    if (
      !isRecord(value) ||
      value['version'] !== 1 ||
      value['country'] !== country ||
      !isPlanId(value['id'])
    )
      return null;
    const price = decodePlanPrice(value['price'], country);
    return price ? { id: value['id'], price } : null;
  } catch {
    return null;
  }
}

@Injectable({ providedIn: 'root' })
export class PlanState {
  private readonly http = inject(HttpClient);
  private readonly current = signal<PlanView>({ phase: 'idle' });
  private readonly candidates = signal<Partial<Record<Country, Candidate | null>>>({});
  private request?: Subscription;
  private generation = 0;

  readonly view = this.current.asReadonly();

  leave() {
    this.generation++;
    this.request?.unsubscribe();
    this.current.set({ phase: 'idle' });
  }

  hasCandidate(country: Country) {
    return this.candidate(country) !== null;
  }

  selected(country: Country): Plan | null {
    const state = this.current();
    if (state.phase !== 'ready' || state.country !== country) return null;
    return this.match(state.plans, this.candidate(country));
  }

  choose(country: Country, id: string) {
    const state = this.current();
    if (state.phase !== 'ready' || state.country !== country) return;
    const choice = state.plans.find((plan) => plan.id === id);
    if (!choice) return;
    this.save(country, { id: choice.id, price: choice.basePrice });
    if (state.lostChoice) this.current.set({ ...state, lostChoice: false });
  }

  clearCandidate(country: Country) {
    this.save(country, null);
  }

  read(country: Country, phase: ReadMode) {
    const generation = ++this.generation;
    this.request?.unsubscribe();
    this.current.set({ phase, country });

    const stillCurrent = () => {
      const state = this.current();
      return generation === this.generation && state.phase === phase && state.country === country;
    };
    const unavailable = () => {
      if (stillCurrent()) this.current.set({ phase: 'unavailable', country });
    };
    this.request = this.http
      .get<unknown>(`/api/quote-content/v1/${country}/plans`, { timeout: 10_000 })
      .subscribe({
        next: (input) => {
          if (!stillCurrent()) return;
          const catalog = decodePlanCatalog(input, country);
          if (!catalog) return unavailable();
          const candidate = this.candidate(country);
          const lostChoice = candidate !== null && !this.match(catalog.plans, candidate);
          if (lostChoice) this.clearCandidate(country);
          this.current.set({
            phase: 'ready',
            country,
            plans: catalog.plans,
            lostChoice,
            checkedForSummary: phase === 'checking',
            recovered: phase === 'retrying',
          });
        },
        error: unavailable,
      });
  }

  private candidate(country: Country) {
    const memory = this.candidates()[country];
    return memory === undefined ? restoreCandidate(country) : memory;
  }

  private match(plans: readonly Plan[], candidate: Candidate | null): Plan | null {
    if (!candidate) return null;
    return (
      plans.find(
        ({ id, basePrice }) =>
          id === candidate.id &&
          basePrice.amountMinor === candidate.price.amountMinor &&
          basePrice.currency === candidate.price.currency,
      ) ?? null
    );
  }

  private save(country: Country, candidate: Candidate | null) {
    this.candidates.update((values) => ({ ...values, [country]: candidate }));
    try {
      if (candidate) {
        sessionStorage.setItem(
          candidateKey(country),
          JSON.stringify({ version: 1, country, ...candidate }),
        );
      } else {
        sessionStorage.removeItem(candidateKey(country));
      }
    } catch {
      // Selection remains available in memory for the current page session.
    }
  }
}

import { isCountry, MAX_PLANS } from "@quote/contract";
import { FORM_UID, projectForm } from "../form-projection";

import { PLAN_UID, projectPlans } from "../plan-projection";

type ReadContext = {
  params: Record<string, unknown>;
  querystring: string;
  set(name: string, value: string): void;
  status: number;
  body: unknown;
};

function startRead(ctx: ReadContext) {
  ctx.set("Cache-Control", "no-store");
  return (status: number, code: string) => {
    ctx.body = { error: { code } };
    ctx.status = status;
  };
}

export default {
  async readForm(ctx: ReadContext) {
    const fail = startRead(ctx);
    const country = ctx.params["country"];
    if (!isCountry(country)) return fail(404, "UNSUPPORTED_COUNTRY");
    if (ctx.querystring) return fail(400, "INVALID_REQUEST");

    let documents;
    try {
      documents = await strapi.documents(FORM_UID).findMany({
        status: "published",
        filters: { country },
        populate: { fields: { populate: ["options", "rules"] } },
        limit: 2,
      });
    } catch {
      strapi.log.error("Quote form document retrieval failed.");
      return fail(503, "CONTENT_UNAVAILABLE");
    }

    if (!documents.length) return fail(404, "FORM_NOT_PUBLISHED");
    const form =
      documents.length === 1 ? projectForm(documents[0], country) : null;
    if (!form) {
      strapi.log.warn("A published quote form configuration was rejected.");
      return fail(503, "FORM_UNAVAILABLE");
    }
    ctx.body = form;
    ctx.status = 200;
  },
  async readPlans(ctx: ReadContext) {
    const fail = startRead(ctx);
    const country = ctx.params["country"];
    if (!isCountry(country)) return fail(404, "UNSUPPORTED_COUNTRY");
    if (ctx.querystring) return fail(400, "INVALID_REQUEST");

    let documents;
    try {
      documents = await strapi.documents(PLAN_UID).findMany({
        status: "published",
        filters: { country, active: true },
        populate: ["coverages", "benefits"],
        limit: MAX_PLANS + 1,
      });
    } catch {
      strapi.log.error("Quote plan document retrieval failed.");
      return fail(503, "CONTENT_UNAVAILABLE");
    }

    const catalog = projectPlans(documents, country);
    if (!catalog) {
      strapi.log.warn("A published quote plan catalog was rejected.");
      return fail(503, "PLANS_UNAVAILABLE");
    }
    ctx.body = catalog;
    ctx.status = 200;
  },
};
server {
  listen 80;
  root /usr/share/nginx/html;
  index index.html;

  location ~ ^/api/quote-content/v1/[^/]+/(form|plans)$ {
    if ($request_method != GET) { return 405; }
    proxy_pass http://cms:1337;
    proxy_cache off;
    proxy_connect_timeout 3s;
    proxy_read_timeout 10s;
  }

  location /api/ { return 404; }
  location = /api { return 404; }
  location /admin { return 404; }
  location ~ ^/[^/]+/quote/[^/]+/?$ { try_files /index.html =404; }
  location ~ \.[A-Za-z0-9]+$ { try_files $uri =404; }
  location / { try_files $uri $uri/ /index.html; }
}
