@Component({
  selector: 'app-plan-list',
  imports: [RouterLink],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './plan-list.html',
})
export class PlanList {
  readonly country = input.required<Country>();
  readonly complete = output<void>();
  protected readonly store = inject(PlanState);
  private readonly injector = inject(Injector);
  private readonly heading = viewChild.required<ElementRef<HTMLElement>>('heading');
  private retryHadFocus = false;
  protected readonly view = computed(() => {
    const state = this.store.view();
    return state.phase !== 'idle' && state.country === this.country()
      ? state
      : { phase: 'loading' as const };
  });
  protected readonly selected = computed(() => this.store.selected(this.country()));
  protected readonly countryLabel = computed(() =>
    this.country() === 'co' ? 'Colombia' : 'Chile',
  );
  protected readonly status = computed(() => {
    const state = this.view();
    switch (state.phase) {
      case 'loading':
      case 'retrying':
        return 'Cargando los planes…';
      case 'checking':
        return 'Verificando tu plan…';
      case 'unavailable':
        return 'No pudimos cargar los planes. Intenta de nuevo.';
      case 'ready':
        if (state.lostChoice)
          return state.plans.length
            ? 'Tu plan cambió o ya no está disponible. Selecciona un plan para continuar.'
            : 'Tu plan cambió o ya no está disponible.';
        if (!state.plans.length) return 'No hay planes disponibles.';
        return state.recovered ? 'Planes disponibles.' : '';
    }
  });

  constructor() {
    effect(() => {
      this.country();
      this.focusHeading();
    });

    effect(() => {
      const state = this.view();
      if (state.phase === 'retrying') return;
      if (state.phase === 'ready' && state.recovered && this.retryHadFocus) {
        afterNextRender(
          () => {
            const focused = document.activeElement;
            if (focused === document.body) this.heading().nativeElement.focus();
          },
          { injector: this.injector },
        );
      }
      this.retryHadFocus = false;
    });
  }

  protected retry(event: MouseEvent) {
    if (this.view().phase !== 'unavailable') return;
    this.retryHadFocus = document.activeElement === event.currentTarget;
    this.store.read(this.country(), 'retrying');
  }

  protected proceed() {
    if (!this.selected()) return;
    this.heading().nativeElement.focus();
    this.complete.emit();
  }

  protected displayPrice(price: PlanPrice) {
    const scale = price.currency === 'COP' ? 100 : 1;
    return priceFormat[price.currency].format(price.amountMinor / scale);
  }

  private focusHeading() {
    afterNextRender(() => this.heading().nativeElement.focus(), { injector: this.injector });
  }
}
import { HttpClient } from '@angular/common/http';
import { inject, Injectable, signal } from '@angular/core';
import {
  decodePlanCatalog,
  decodePlanPrice,
  isPlanId,
  isRecord,
  type Country,
  type Plan,
  type PlanPrice,
} from '@quote/contract';
import type { Subscription } from 'rxjs';

type Candidate = { id: string; price: PlanPrice };
type ReadMode = 'loading' | 'retrying' | 'checking';

export type PlanView =
  | { phase: 'idle' }
  | { phase: ReadMode | 'unavailable'; country: Country }
  | {
      phase: 'ready';
      country: Country;
      plans: readonly Plan[];
      lostChoice: boolean;
      checkedForSummary: boolean;
      recovered: boolean;
    };

function candidateKey(country: Country) {
  return `quote-plan-v1:${country}`;
}

function restoreCandidate(country: Country): Candidate | null {
  try {
    const text = sessionStorage.getItem(candidateKey(country));
    if (!text || text.length > 512) return null;
    const value: unknown = JSON.parse(text);
    if (
      !isRecord(value) ||
      value['version'] !== 1 ||
      value['country'] !== country ||
      !isPlanId(value['id'])
    )
      return null;
    const price = decodePlanPrice(value['price'], country);
    return price ? { id: value['id'], price } : null;
  } catch {
    return null;
  }
}

@Injectable({ providedIn: 'root' })
export class PlanState {
  private readonly http = inject(HttpClient);
  private readonly current = signal<PlanView>({ phase: 'idle' });
  private readonly candidates = signal<Partial<Record<Country, Candidate | null>>>({});
  private request?: Subscription;
  private generation = 0;

  readonly view = this.current.asReadonly();

  leave() {
    this.generation++;
    this.request?.unsubscribe();
    this.current.set({ phase: 'idle' });
  }

  hasCandidate(country: Country) {
    return this.candidate(country) !== null;
  }

  selected(country: Country): Plan | null {
    const state = this.current();
    if (state.phase !== 'ready' || state.country !== country) return null;
    return this.match(state.plans, this.candidate(country));
  }

  choose(country: Country, id: string) {
    const state = this.current();
    if (state.phase !== 'ready' || state.country !== country) return;
    const choice = state.plans.find((plan) => plan.id === id);
    if (!choice) return;
    this.save(country, { id: choice.id, price: choice.basePrice });
    if (state.lostChoice) this.current.set({ ...state, lostChoice: false });
  }

  clearCandidate(country: Country) {
    this.save(country, null);
  }

  read(country: Country, phase: ReadMode) {
    const generation = ++this.generation;
    this.request?.unsubscribe();
    this.current.set({ phase, country });

    const stillCurrent = () => {
      const state = this.current();
      return generation === this.generation && state.phase === phase && state.country === country;
    };
    const unavailable = () => {
      if (stillCurrent()) this.current.set({ phase: 'unavailable', country });
    };
    this.request = this.http
      .get<unknown>(`/api/quote-content/v1/${country}/plans`, { timeout: 10_000 })
      .subscribe({
        next: (input) => {
          if (!stillCurrent()) return;
          const catalog = decodePlanCatalog(input, country);
          if (!catalog) return unavailable();
          const candidate = this.candidate(country);
          const lostChoice = candidate !== null && !this.match(catalog.plans, candidate);
          if (lostChoice) this.clearCandidate(country);
          this.current.set({
            phase: 'ready',
            country,
            plans: catalog.plans,
            lostChoice,
            checkedForSummary: phase === 'checking',
            recovered: phase === 'retrying',
          });
        },
        error: unavailable,
      });
  }

  private candidate(country: Country) {
    const memory = this.candidates()[country];
    return memory === undefined ? restoreCandidate(country) : memory;
  }

  private match(plans: readonly Plan[], candidate: Candidate | null): Plan | null {
    if (!candidate) return null;
    return (
      plans.find(
        ({ id, basePrice }) =>
          id === candidate.id &&
          basePrice.amountMinor === candidate.price.amountMinor &&
          basePrice.currency === candidate.price.currency,
      ) ?? null
    );
  }

  private save(country: Country, candidate: Candidate | null) {
    this.candidates.update((values) => ({ ...values, [country]: candidate }));
    try {
      if (candidate) {
        sessionStorage.setItem(
          candidateKey(country),
          JSON.stringify({ version: 1, country, ...candidate }),
        );
      } else {
        sessionStorage.removeItem(candidateKey(country));
      }
    } catch {
      // Selection remains available in memory for the current page session.
    }
  }
}

import { isCountry, MAX_PLANS } from "@quote/contract";
import { FORM_UID, projectForm } from "../form-projection";

import { PLAN_UID, projectPlans } from "../plan-projection";

type ReadContext = {
  params: Record<string, unknown>;
  querystring: string;
  set(name: string, value: string): void;
  status: number;
  body: unknown;
};

function startRead(ctx: ReadContext) {
  ctx.set("Cache-Control", "no-store");
  return (status: number, code: string) => {
    ctx.body = { error: { code } };
    ctx.status = status;
  };
}

export default {
  async readForm(ctx: ReadContext) {
    const fail = startRead(ctx);
    const country = ctx.params["country"];
    if (!isCountry(country)) return fail(404, "UNSUPPORTED_COUNTRY");
    if (ctx.querystring) return fail(400, "INVALID_REQUEST");

    let documents;
    try {
      documents = await strapi.documents(FORM_UID).findMany({
        status: "published",
        filters: { country },
        populate: { fields: { populate: ["options", "rules"] } },
        limit: 2,
      });
    } catch {
      strapi.log.error("Quote form document retrieval failed.");
      return fail(503, "CONTENT_UNAVAILABLE");
    }

    if (!documents.length) return fail(404, "FORM_NOT_PUBLISHED");
    const form =
      documents.length === 1 ? projectForm(documents[0], country) : null;
    if (!form) {
      strapi.log.warn("A published quote form configuration was rejected.");
      return fail(503, "FORM_UNAVAILABLE");
    }
    ctx.body = form;
    ctx.status = 200;
  },
  async readPlans(ctx: ReadContext) {
    const fail = startRead(ctx);
    const country = ctx.params["country"];
    if (!isCountry(country)) return fail(404, "UNSUPPORTED_COUNTRY");
    if (ctx.querystring) return fail(400, "INVALID_REQUEST");

    let documents;
    try {
      documents = await strapi.documents(PLAN_UID).findMany({
        status: "published",
        filters: { country, active: true },
        populate: ["coverages", "benefits"],
        limit: MAX_PLANS + 1,
      });
    } catch {
      strapi.log.error("Quote plan document retrieval failed.");
      return fail(503, "CONTENT_UNAVAILABLE");
    }

    const catalog = projectPlans(documents, country);
    if (!catalog) {
      strapi.log.warn("A published quote plan catalog was rejected.");
      return fail(503, "PLANS_UNAVAILABLE");
    }
    ctx.body = catalog;
    ctx.status = 200;
  },
};
server {
  listen 80;
  root /usr/share/nginx/html;
  index index.html;

  location ~ ^/api/quote-content/v1/[^/]+/(form|plans)$ {
    if ($request_method != GET) { return 405; }
    proxy_pass http://cms:1337;
    proxy_cache off;
    proxy_connect_timeout 3s;
    proxy_read_timeout 10s;
  }

  location /api/ { return 404; }
  location = /api { return 404; }
  location /admin { return 404; }
  location ~ ^/[^/]+/quote/[^/]+/?$ { try_files /index.html =404; }
  location ~ \.[A-Za-z0-9]+$ { try_files $uri =404; }
  location / { try_files $uri $uri/ /index.html; }
}
import assert from "node:assert/strict";
import { randomBytes } from "node:crypto";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { once } from "node:events";
import test from "node:test";
import { createRequire } from "node:module";

const { createStrapi, compileStrapi } = createRequire(import.meta.url)(
  "@strapi/strapi",
);

test("T-US01-05/08/09 and T-US02-01/02/05: publish, change and unpublish isolated CMS content", async () => {
  const fixture = await mkdtemp(join(tmpdir(), "quote-cms-test-"));
  const secret = () => randomBytes(32).toString("hex");
  Object.assign(process.env, {
    DATABASE_FILENAME: join(fixture, "strapi.sqlite"),
    STRAPI_TELEMETRY_DISABLED: "true",
    HOST: "127.0.0.1",
    APP_KEYS: [secret(), secret()].join(","),
    ADMIN_JWT_SECRET: secret(),
    API_TOKEN_SALT: secret(),
    JWT_SECRET: secret(),
    TRANSFER_TOKEN_SALT: secret(),
    ENCRYPTION_KEY: secret(),
  });

  const context = await compileStrapi({ appDir: resolve(".") });
  let app = createStrapi(context);
  const readPermission = "api::quote-content.quote-content.readForm";
  const readPlansPermission = "api::quote-content.quote-content.readPlans";
  const roles = () => app.db.query("plugin::users-permissions.role");
  const permissions = () =>
    app.db.query("plugin::users-permissions.permission");
  async function roleActions(type) {
    const role = await roles().findOne({ where: { type } });
    assert.ok(role);
    const rows = await permissions().findMany({ where: { role: role.id } });
    return rows.map(({ action }) => action).sort();
  }
  try {
    await app.load();
    app.server.listen(0, "127.0.0.1");
    await once(app.server.httpServer, "listening");
    const { port } = app.server.httpServer.address();
    const uri = `http://127.0.0.1:${port}/api/quote-content/v1/co/form`;
    const current = async () => {
      const response = await fetch(uri);
      assert.equal(response.status, 200);
      assert.equal(response.headers.get("cache-control"), "no-store");
      return response.json();
    };

    // T-US02-01/02/05: the dedicated collection publishes independently.
    const plansUri = uri.replace("/form", "/plans");
    const readPlans = async (target = plansUri) => {
      const response = await fetch(target);
      assert.equal(response.status, 200);
      assert.equal(response.headers.get("cache-control"), "no-store");
      return response.json();
    };
    const initialPlans = await readPlans();
    assert.equal(initialPlans.country, "co");
    assert.ok(initialPlans.plans.length >= 2);
    const chilePlans = await readPlans(plansUri.replace("/co/", "/cl/"));
    assert.equal(chilePlans.country, "cl");
    assert.ok(chilePlans.plans.length);
    assert.ok(
      chilePlans.plans.every(({ basePrice }) => basePrice.currency === "CLP"),
    );
    const plans = app.documents("api::quote-content.plan");
    const selectedId = initialPlans.plans[0].id;
    await plans.update({
      documentId: selectedId,
      status: "draft",
      data: {
        name: "Plan ficticio revisado",
        basePrice: 129900.5,
        active: false,
      },
    });
    assert.deepEqual(await readPlans(), initialPlans);
    await plans.publish({ documentId: selectedId });
    assert.equal(
      (await readPlans()).plans.some(({ id }) => id === selectedId),
      false,
    );
    await plans.update({
      documentId: selectedId,
      status: "published",
      data: { active: true },
    });
    assert.deepEqual(
      (await readPlans()).plans.find(({ id }) => id === selectedId)?.basePrice,
      { amountMinor: 12990050, currency: "COP" },
    );
    for (const { id } of initialPlans.plans)
      await plans.unpublish({ documentId: id });
    assert.deepEqual((await readPlans()).plans, []);
    assert.equal((await fetch(plansUri + "?status=draft")).status, 400);
    assert.equal((await fetch(new URL("/api/plans", plansUri))).status, 404);

    const initial = await current();
    assert.equal(
      initial.fields.find(({ id }) => id === "accessories").defaultValue,
      false,
    );
    assert.equal(
      initial.fields.some(({ id }) => id === "agency"),
      false,
    );

    const documents = app.documents("api::quote-content.form-configuration");
    const draft = await documents.findFirst({
      status: "draft",
      filters: { country: "co" },
      populate: { fields: { populate: ["options", "rules"] } },
    });
    assert.ok(draft);
    const added = {
      fieldKey: "agency",
      label: "Agencia de ejemplo",
      helpText: "",
      errorMessage: "Revisa la agencia.",
      kind: "text",
      required: false,
      order: 35,
    };
    const serverLocalTooOld = new Date().getFullYear() - 21;
    await documents.update({
      documentId: draft.documentId,
      status: "draft",
      data: {
        fields: [
          ...draft.fields
            .filter(({ fieldKey }) => fieldKey !== "accessories")
            .map((field) =>
              field.fieldKey === "vehicle-year"
                ? { ...field, defaultValue: { value: serverLocalTooOld } }
                : field,
            ),
          added,
        ],
      },
    });
    assert.deepEqual(await current(), initial);

    await documents.publish({ documentId: draft.documentId });
    const published = await current();
    assert.equal(
      published.fields.find(({ id }) => id === "vehicle-year").defaultValue,
      serverLocalTooOld,
      "the API serves structurally valid defaults for the browser to validate against its civil date",
    );
    assert.equal(
      published.fields.some(({ id }) => id === "accessories"),
      false,
    );
    assert.equal(
      published.fields.find(({ id }) => id === "agency").label,
      "Agencia de ejemplo",
    );
    assert.equal(
      published.fields.findIndex(({ id }) => id === "agency"),
      published.fields.findIndex(({ id }) => id === "identity-document") + 1,
    );

    await documents.unpublish({ documentId: draft.documentId });
    const unavailable = await fetch(uri);
    assert.equal(unavailable.status, 404);
    assert.deepEqual(await unavailable.json(), {
      error: { code: "FORM_NOT_PUBLISHED" },
    });
    const chile = await fetch(uri.replace("/co/", "/cl/"));
    assert.equal(chile.status, 200);
    assert.equal((await chile.json()).country, "cl");

    // US01-R05: anonymous permissions are distinct from Strapi administrators.
    assert.deepEqual(await roleActions("public"), [
      readPermission,
      readPlansPermission,
    ]);
    const base = new URL(uri).origin;
    assert.equal((await fetch(`${base}/admin/init`)).status, 200);
    assert.equal(
      (await fetch(`${base}/api/auth/email-confirmation`)).status,
      403,
    );
    const authenticatedActions = await roleActions("authenticated");
    const publicRole = await roles().findOne({ where: { type: "public" } });
    await permissions().create({
      data: {
        role: publicRole.id,
        action: "plugin::users-permissions.auth.register",
      },
    });
    await app.destroy();

    app = createStrapi(context);
    await app.load();
    assert.deepEqual(await roleActions("public"), [
      readPermission,
      readPlansPermission,
    ]);
    assert.deepEqual(await roleActions("authenticated"), authenticatedActions);
    const co = await app
      .documents("api::quote-content.form-configuration")
      .findFirst({
        status: "published",
        filters: { country: "co" },
      });
    assert.equal(
      co,
      null,
      "restarting the initialized fixture preserves unpublication",
    );
    const restartedPlans = await app
      .documents("api::quote-content.plan")
      .findMany({
        status: "published",
        filters: { country: "co" },
      });
    assert.deepEqual(
      restartedPlans,
      [],
      "a restart preserves deliberately unpublished plans",
    );
  } finally {
    await app.destroy();
    await rm(fixture, { recursive: true, force: true });
  }
});

