import { RouterTestingHarness } from '@angular/router/testing';
import { afterEach, describe, expect, it } from 'vitest';
import { routes } from '../app.routes';
import { QuoteState } from './quote-state';

const countryField = (country: 'co' | 'cl') => ({
  id: 'identity',
