  errorMessage: 'Completa el documento',
  rules: [],
});
const sharedField = { required: true, helpText: '', errorMessage: 'Completa el campo' };
const configuration = (country: 'co' | 'cl') => ({
  schemaVersion: 1,
  country,
  fields: [
    {
      ...sharedField,
      id: 'birth',
      purpose: 'dateOfBirth',
      kind: 'date',
      order: 20,
      label: 'Nacimiento',
