import assert from "node:assert/strict";
import { randomBytes } from "node:crypto";
import { mkdtemp, rm } from "node:fs/promises";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import test from "node:test";

const require = createRequire(import.meta.url);
const { createStrapi, compileStrapi } = require("@strapi/strapi");

test("US-02 development plan sync preserves documents and stops on editor changes", async () => {
  const fixture = await mkdtemp(join(tmpdir(), "quote-plan-sync-"));
  const secret = () => randomBytes(32).toString("hex");
  Object.assign(process.env, {
    DATABASE_FILENAME: join(fixture, "strapi.sqlite"),
    STRAPI_TELEMETRY_DISABLED: "true",
    APP_KEYS: [secret(), secret()].join(","),
    ADMIN_JWT_SECRET: secret(),
    API_TOKEN_SALT: secret(),
    JWT_SECRET: secret(),
    TRANSFER_TOKEN_SALT: secret(),
    ENCRYPTION_KEY: secret(),
  });

  const context = await compileStrapi({ appDir: resolve(".") });
  const app = createStrapi(context);
  try {
    await app.load();
    const { syncDevPlans } = require("../dist/src/dev-plan-sync.js");
    const { PLAN_EXPANSION_KEY } = require("../dist/src/seed-plans.js");
    const plans = app.documents("api::quote-content.plan");
    const store = app.store({ type: "core", name: "quote-content" });
    const fixtureBenefits = [{ text: "Asistencia en carretera" }];
    const legacy = (await plans.findMany({ status: "draft" })).filter(
      ({ name }) => name !== "Integral",
    );
    const initial = await syncDevPlans(app);
    assert.equal(
      initial.status,
      "noop",
      "fresh seed already includes all plans",
    );
    assert.equal(
      Object.keys(await store.get({ key: PLAN_EXPANSION_KEY })).length,
      2,
    );
    for (const { documentId, name } of await plans.findMany({
      status: "draft",
    })) {
      if (name === "Integral") await plans.delete({ documentId });
      else
        await plans.update({
          documentId,
          status: "published",
          data: { benefits: fixtureBenefits },
        });
    }
    await store.delete({ key: PLAN_EXPANSION_KEY });

    const unrelated = await plans.create({
      data: {
        country: "co",
        name: "Plan adicional de prueba",
        shortDescription: "Sin publicar",
        basePrice: 10000,
        currency: "COP",
        active: false,
        recommended: false,
        order: 90,
      },
      status: "draft",
    });
    const admin = await app.service("admin::user").create({
      firstname: "Test",
      lastname: "Fixture",
      email: "catalog-sync@example.test",
      password: secret(),
      isActive: true,
    });
    const draftFields = (documentId) =>
      plans.findOne({ documentId, status: "draft", populate: ["benefits"] });
    const publishedFields = (documentId) =>
      plans.findOne({
        documentId,
        status: "published",
        populate: ["benefits"],
      });
    const originalCo = legacy.find(
      ({ country, name }) => country === "co" && name === "Esencial",
    );
    const ready = await syncDevPlans(app);
    assert.equal(ready.status, "ready");
    assert.equal(
      ready.actions.filter(({ kind }) => kind === "update").length,
      4,
    );
    assert.equal(
      ready.actions.filter(({ kind }) => kind === "create").length,
      2,
    );
    assert.equal(
      (await publishedFields(originalCo.documentId)).benefits.length,
      1,
      "dry run does not write",
    );

    await plans.update({
      documentId: originalCo.documentId,
      status: "draft",
      data: { shortDescription: "Cambio editorial" },
    });
    assert.equal(
      (await syncDevPlans(app, ready.fingerprint)).status,
      "blocked",
    );
    assert.equal(
      (await draftFields(originalCo.documentId)).shortDescription,
      "Cambio editorial",
    );
    for (const document of legacy)
      assert.equal(
        (await publishedFields(document.documentId)).benefits.length,
        1,
      );
    assert.equal(
      (await plans.findMany({ filters: { name: "Integral" }, status: "draft" }))
        .length,
      0,
    );
    await plans.discardDraft({ documentId: originalCo.documentId });

    assert.equal((await syncDevPlans(app, "0".repeat(64))).status, "stale");

    const coRuta = legacy.find(
      ({ country, name }) => country === "co" && name === "Ruta",
    );
    const preservedPrice = "179900.00";
    await plans.update({
      documentId: coRuta.documentId,
      status: "published",
      data: { basePrice: Number(preservedPrice) },
    });
    assert.equal((await syncDevPlans(app)).status, "blocked");
    assert.equal(
      (await syncDevPlans(app, undefined, "179900.01")).status,
      "blocked",
    );
    const verified = await syncDevPlans(app, undefined, preservedPrice);
    assert.equal(verified.status, "ready");
    assert.notEqual(verified.fingerprint, ready.fingerprint);
    assert.equal(
      (await syncDevPlans(app, ready.fingerprint, preservedPrice)).status,
      "stale",
    );
    assert.equal(
      (await syncDevPlans(app, verified.fingerprint)).status,
      "blocked",
    );

    await plans.update({
      documentId: coRuta.documentId,
      status: "draft",
      data: { basePrice: 180000 },
    });
    assert.equal(
      (await syncDevPlans(app, verified.fingerprint, preservedPrice)).status,
      "blocked",
    );
    await plans.discardDraft({ documentId: coRuta.documentId });
    await plans.update({
      documentId: coRuta.documentId,
      status: "draft",
      data: { recommended: false },
    });
    assert.equal(
      (await syncDevPlans(app, verified.fingerprint, preservedPrice)).status,
      "blocked",
    );
    await plans.discardDraft({ documentId: coRuta.documentId });
    assert.equal(
      (await syncDevPlans(app, verified.fingerprint, preservedPrice)).status,
      "applied",
    );
    for (const document of legacy) {
      const draft = await draftFields(document.documentId);
      const published = await publishedFields(document.documentId);
      assert.equal(draft.name, document.name);
      const expectedPrice =
        document.documentId === coRuta.documentId
          ? Number(preservedPrice)
          : document.basePrice;
      assert.equal(draft.basePrice, expectedPrice);
      assert.equal(published.basePrice, expectedPrice);
      assert.ok(draft.benefits.length > 1);
      assert.deepEqual(
        draft.benefits.map(({ text }) => text),
        published.benefits.map(({ text }) => text),
      );
    }
    assert.equal(
      (await draftFields(unrelated.documentId)).name,
      unrelated.name,
    );
    assert.equal(await publishedFields(unrelated.documentId), null);
    assert.equal(
      (await app.db.query("admin::user").findOne({ where: { id: admin.id } }))
        .email,
      admin.email,
    );
    const noOp = await syncDevPlans(app, undefined, preservedPrice);
    assert.equal(noOp.status, "noop");
    assert.equal(
      (await syncDevPlans(app, noOp.fingerprint, preservedPrice)).status,
      "noop",
    );
    assert.equal(
      (await plans.findMany({ filters: { name: "Integral" }, status: "draft" }))
        .length,
      2,
    );

    const { co, cl } = await store.get({ key: PLAN_EXPANSION_KEY });
    await plans.unpublish({ documentId: co });
    await plans.delete({ documentId: cl });
    assert.equal(
      (await syncDevPlans(app, undefined, preservedPrice)).status,
      "blocked",
    );
    assert.equal(await publishedFields(co), null);
    assert.equal(await draftFields(cl), null);
  } finally {
    await app.destroy();
    await rm(fixture, { recursive: true, force: true });
  }
});

import { createHash } from "node:crypto";
import { isPlanId, isRecord, type Country } from "@quote/contract";
import type { Core } from "@strapi/strapi";
import { PLAN_UID, projectPlans } from "./api/quote-content/plan-projection";
import {
  originalSeedPlans,
  PLAN_EXPANSION_KEY,
  planCountries,
  seedPlans,
} from "./seed-plans";

const statuses = ["draft", "published"] as const;
type Versions = Record<(typeof statuses)[number], readonly unknown[]>;
type ComparablePlan = Record<string, unknown> & { country: Country };
type Action = {
  country: Country;
  name: string;
} & ({ kind: "keep" | "update"; documentId: string } | { kind: "create" });
type Report = {
  actions: Action[];
  conflicts: string[];
  fingerprint: string;
  preserveCoRutaPrice?: string;
  status: "blocked" | "ready" | "noop" | "stale" | "applied";
};

function fingerprintFor(value: unknown) {
  return createHash("sha256").update(JSON.stringify(value)).digest("hex");
}

function canonical(plan: Record<string, unknown>, country: Country) {
  const projected = projectPlans([{ ...plan, documentId: "fixture" }], country);
  return projected ? JSON.stringify(projected.plans[0]) : null;
}

function unchanged(plan: unknown, fixture: ComparablePlan) {
  const expected = canonical(fixture, fixture.country);
  return (
    expected !== null &&
    isRecord(plan) &&
    canonical(plan, fixture.country) === expected
  );
}

function byName(
  raw: unknown,
  country: Country,
  name: string,
): raw is Record<string, unknown> {
  return (
    isRecord(raw) &&
    raw["country"] === country &&
    typeof raw["name"] === "string" &&
    raw["name"].trim().toLowerCase() === name.toLowerCase()
  );
}

function matches(versions: Versions, country: Country, name: string) {
  return {
    draft: versions.draft.filter((raw) => byName(raw, country, name)),
    published: versions.published.filter((raw) => byName(raw, country, name)),
  };
}

function pair(candidates: ReturnType<typeof matches>) {
  const [draft] = candidates.draft;
  const [published] = candidates.published;
  const id = draft?.["documentId"];
  if (
    candidates.draft.length !== 1 ||
    candidates.published.length !== 1 ||
    !isPlanId(id) ||
    published?.["documentId"] !== id
  )
    return null;
  return { draft, published, id };
}

function planSync(
  versions: Versions,
  provenance: unknown,
  coRutaPrice: number | undefined,
) {
  const conflicts: string[] = [];
  const actions: Action[] = [];
  const tracked =
    isRecord(provenance) &&
    isPlanId(provenance["co"]) &&
    isPlanId(provenance["cl"]) &&
    provenance["co"] !== provenance["cl"]
      ? provenance
      : null;
  if (provenance != null && !tracked)
    conflicts.push("The saved Integral provenance is invalid.");

  for (const country of planCountries) {
    const originals = originalSeedPlans(country);
    const targets = seedPlans(country);
    for (const index of [0, 1] as const) {
      const preservePrice =
        country === "co" && originals[index].name === "Ruta"
          ? coRutaPrice
          : undefined;
      const original = {
        ...originals[index],
        basePrice: preservePrice ?? originals[index].basePrice,
      };
      const target = {
        ...targets[index],
        basePrice: preservePrice ?? targets[index].basePrice,
      };
      const { name } = original;
      const stock = pair(matches(versions, country, name));
      if (!stock) {
        conflicts.push(
          `${country}/${name}: expected one document with both draft and published versions.`,
        );
      } else if (
        unchanged(stock.draft, target) &&
        unchanged(stock.published, target)
      ) {
        actions.push({ country, name, kind: "keep", documentId: stock.id });
      } else if (
        unchanged(stock.draft, original) &&
        unchanged(stock.published, original)
      ) {
        actions.push({ country, name, kind: "update", documentId: stock.id });
      } else {
        conflicts.push(
          `${country}/${name}: draft or published content differs from the fixture pair.`,
        );
      }
    }
  }

  const missingIntegral: Country[] = [];
  for (const country of planCountries) {
    const target = seedPlans(country)[2];
    const { name } = target;
    const candidates = matches(versions, country, name);
    if (!tracked && !candidates.draft.length && !candidates.published.length) {
      const renamed = statuses.some((status) =>
        versions[status].some(
          (plan) => isRecord(plan) && unchanged({ ...plan, name }, target),
        ),
      );
      if (renamed)
        conflicts.push(
          `${country}/${name}: found equivalent content under a different name.`,
        );
      else missingIntegral.push(country);
      continue;
    }
    const stock = pair(candidates);
    if (
      !stock ||
      (tracked && tracked[country] !== stock.id) ||
      !unchanged(stock.draft, target) ||
      !unchanged(stock.published, target)
    ) {
      conflicts.push(
        `${country}/${name}: the document is missing, ambiguous, unpublished or edited.`,
      );
    } else {
      actions.push({ country, name, kind: "keep", documentId: stock.id });
    }
  }
  if (missingIntegral.length) {
    const pristine =
      actions.length === 4 && actions.every(({ kind }) => kind === "update");
    if (missingIntegral.length === 2 && pristine && !conflicts.length) {
      for (const country of missingIntegral)
        actions.push({ country, name: "Integral", kind: "create" });
    } else {
      for (const country of missingIntegral) {
        conflicts.push(
          `${country}/Integral: absence is ambiguous without the pristine original fixture.`,
        );
      }
    }
  }
  return { actions, conflicts };
}

export async function syncDevPlans(
  strapi: Core.Strapi,
  applyFingerprint?: string,
  preserveCoRutaPrice?: string,
): Promise<Report> {
  if (
    preserveCoRutaPrice !== undefined &&
    !/^(0|[1-9][0-9]{0,9})\.[0-9]{2}$/.test(preserveCoRutaPrice)
  )
    throw new Error(
      "Enter the approved CO Ruta price in COP major units, with two decimal places and no separators.",
    );

  const coRutaPrice =
    preserveCoRutaPrice === undefined ? undefined : Number(preserveCoRutaPrice);
  const store = strapi.store({ type: "core", name: "quote-content" });
  return strapi.db.transaction(async (): Promise<Report> => {
    const documents = strapi.documents(PLAN_UID);
    const populate = ["coverages", "benefits"];
    const versions = {
      draft: await documents.findMany({ status: "draft", populate }),
      published: await documents.findMany({ status: "published", populate }),
    };
    const provenance: unknown = await store.get({ key: PLAN_EXPANSION_KEY });
    const { actions, conflicts } = planSync(versions, provenance, coRutaPrice);
    if ((await store.get({ key: "us02-seeded" })) !== true)
      conflicts.push("This database has no initialized US-02 seed marker.");
    const fingerprint = fingerprintFor([
      actions,
      conflicts,
      provenance,
      planCountries.map(seedPlans),
      preserveCoRutaPrice,
    ]);
    const report = { actions, conflicts, fingerprint, preserveCoRutaPrice };
    if (conflicts.length) return { ...report, status: "blocked" };
    if (applyFingerprint !== undefined && applyFingerprint !== fingerprint)
      return { ...report, status: "stale" };
    if (actions.every(({ kind }) => kind === "keep"))
      return { ...report, status: "noop" };
    if (applyFingerprint === undefined) return { ...report, status: "ready" };

    const created: Partial<Record<Country, string>> = {};
    for (const action of actions) {
      if (action.kind === "keep") continue;
      const target = seedPlans(action.country).find(
        ({ name }) => name === action.name,
      );
      if (!target) throw new Error("Target plan is missing from the fixture.");
      if (action.kind === "update") {
        const data: Record<string, unknown> = { benefits: target.benefits };
        await documents.update({
          documentId: action.documentId,
          status: "published",
          data,
        });
      } else {
        const plan = await documents.create({
          data: target,
          status: "published",
        });
        created[action.country] = plan.documentId;
      }
    }
    if (created.co && created.cl)
      await store.set({ key: PLAN_EXPANSION_KEY, value: created });
    return { ...report, status: "applied" };
  });
}
import { createRequire } from "node:module";
import { chmod, mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { parseArgs } from "node:util";

const require = createRequire(import.meta.url);
const database = "/data/strapi.sqlite";
const { values } = parseArgs({
  options: {
    "dry-run": { type: "boolean" },
    apply: { type: "string" },
    "preserve-co-ruta-price": { type: "string" },
  },
});
const fingerprint = values.apply;
const dryRun = values["dry-run"] && fingerprint === undefined;
const apply = !values["dry-run"] && /^[a-f0-9]{64}$/.test(fingerprint ?? "");
if (
  process.env.QUOTE_DEV_CATALOG_MAINTENANCE !== "local-compose" ||
  (!dryRun && !apply)
) {
  throw new Error(
    "Run this maintenance command through scripts/sync-dev-plans.sh.",
  );
}

const secrets = JSON.parse(
  await readFile("/data/strapi-local-secrets.json", "utf8"),
);
Object.assign(process.env, secrets, { STRAPI_TELEMETRY_DISABLED: "true" });
const { createStrapi } = require("@strapi/strapi");
const SQLite = require("better-sqlite3");
const { syncDevPlans } = require("../dist/src/dev-plan-sync.js");

async function snapshot(target) {
  const source = new SQLite(database, { readonly: true, fileMustExist: true });
  try {
    await source.backup(target);
    await chmod(target, 0o600);
  } finally {
    source.close();
  }
}

async function run(filename, expectedFingerprint) {
  process.env.DATABASE_FILENAME = filename;
  const app = createStrapi({ appDir: resolve("."), distDir: resolve("dist") });
  app.config.set("quoteCatalogMaintenance", true);
  try {
    await app.load();
    return await syncDevPlans(
      app,
      expectedFingerprint,
      values["preserve-co-ruta-price"],
    );
  } finally {
    await app.destroy();
  }
}

function report(result) {
  console.log(JSON.stringify(result, null, 2));
  if (result.status === "blocked" || result.status === "stale")
    process.exitCode = 1;
}

const workspace = await mkdtemp(join(tmpdir(), "quote-catalog-preview-"));
try {
  const copy = join(workspace, "strapi.sqlite");
  await snapshot(copy);
  const preview = await run(copy);
  if (dryRun || preview.status === "blocked") {
    report(preview);
  } else if (preview.fingerprint !== fingerprint) {
    report({ ...preview, status: "stale" });
  } else if (preview.status === "noop") {
    report(preview);
  } else {
    const backupDirectory = await mkdtemp("/data/.catalog-sync-backup-");
    await snapshot(join(backupDirectory, "strapi.sqlite"));
    console.log(
      `Saved pre-sync database backup at ${backupDirectory}/strapi.sqlite`,
    );
    report(await run(database, fingerprint));
  }
} finally {
  await rm(workspace, { recursive: true, force: true });
}

