  const [published] = candidates.published;
  const id = draft?.["documentId"];
  if (
    candidates.draft.length !== 1 ||
    candidates.published.length !== 1 ||
    !isPlanId(id) ||
    published?.["documentId"] !== id
  )
    return null;
  return { draft, published, id };
}

