import { expect, test } from "@playwright/test";

test("T-US02-MAINT-04: verify published plans in the live development UI", async ({
  page,
}) => {
  const expectedPlans = ["Esencial", "Ruta", "Integral"];
  for (const country of ["co", "cl"] as const) {
    await page.goto(`/${country}/quote/details`);
    await page.getByLabel("Nombre del titular").fill("Conductor ficticio QA");
    if (country === "co") {
      await page.getByLabel("Tipo de documento").selectOption({ index: 1 });
      await page.getByLabel("Número de documento").fill("QA-FICTITIOUS-CO");
      await page.getByLabel("Placa").fill("QA-CO-02");
    } else {
      await page.getByLabel("RUT").fill("QA-FICTITIOUS-CL");
      await page.getByLabel("Patente").fill("QA-CL-02");
    }
    await page.getByLabel("Fecha de nacimiento").fill("1990-02-10");
    const yearField = page.getByLabel("Año del vehículo");
    const maxYear = Number(
      (await yearField.getAttribute("max")) ?? new Date().getFullYear(),
    );
    const minYear = Number((await yearField.getAttribute("min")) ?? 1900);
    await yearField.fill(String(Math.max(minYear, Math.min(maxYear, 2021))));
    await page.getByLabel("Marca").selectOption({ index: 1 });
    await page.getByRole("button", { name: "Continuar" }).click();

    await expect(page).toHaveURL(new RegExp(`/${country}/quote/plans$`));
    await expect(
      page.getByRole("heading", { name: "Elige tu plan" }),
    ).toBeVisible();
    const cards = await page.locator("article").evaluateAll((articles) =>
      articles.map((article) => {
        const name = article.querySelector("label span")?.textContent?.trim();
        const price = article.querySelector("p.text-2xl")?.textContent?.trim();
        const benefitsHeading = Array.from(
          article.querySelectorAll("h2"),
        ).find((heading) => heading.textContent?.trim() === "Beneficios");
        const benefitsList = benefitsHeading?.nextElementSibling;
        return {
          name,
          price,
          benefits: benefitsList
            ? Array.from(benefitsList.querySelectorAll("li"), (item) =>
                item.textContent?.trim(),
              )
            : [],
        };
      }),
    );
    expect(cards.map(({ name }) => name)).toEqual(expectedPlans);
    expect(cards.map(({ benefits }) => benefits.length)).toEqual([3, 4, 5]);
    expect(cards.every(({ benefits }) => benefits.every(Boolean))).toBe(true);
    expect(
      cards.every(({ benefits }) =>
        benefits.includes("Asistencia en carretera"),
      ),
    ).toBe(true);
    if (country === "co")
      expect(cards[1].price?.replace(/\s+/g, " ")).toMatch(
        /COP\s*179\.900,00/,
      );
    else
      expect(cards[1].price?.replace(/\s+/g, " ")).toMatch(/CLP\s*29\.900/);
    expect(await page.getByRole("radio").count()).toBe(3);
    await page.screenshot({
      path: `/private/tmp/us02-live-dev-${country}.png`,
      fullPage: true,
    });
    console.log(
      `LIVE_DEV_${country.toUpperCase()}=${JSON.stringify(cards)}`,
    );
  }
});

