import { expect, test, type Locator, type Page } from "@playwright/test";

test.use({ hasTouch: true });

async function openPlans(page: Page, country: "co" | "cl") {
  await page.goto(`/${country}/quote/details`);
  await page.getByLabel("Nombre del titular").fill("Conductor ficticio QA");
  if (country === "co") {
    await page.getByLabel("Tipo de documento").selectOption({ index: 1 });
    await page.getByLabel("Número de documento").fill("QA-FICTITIOUS-CO");
    await page.getByLabel("Placa").fill("QA-CO-REV");
  } else {
    await page.getByLabel("RUT").fill("QA-FICTITIOUS-CL");
    await page.getByLabel("Patente").fill("QA-CL-REV");
  }
  await page.getByLabel("Fecha de nacimiento").fill("1990-02-10");
  const yearField = page.getByLabel("Año del vehículo");
  const maxYear = Number(
    (await yearField.getAttribute("max")) ?? new Date().getFullYear(),
  );
  const minYear = Number((await yearField.getAttribute("min")) ?? 1900);
  await yearField.fill(String(Math.max(minYear, Math.min(maxYear, 2021))));
  await page.getByLabel("Marca").selectOption({ index: 1 });
  await page.getByRole("button", { name: "Continuar" }).click();
  await expect(page).toHaveURL(new RegExp(`/${country}/quote/plans$`));
  await expect(
    page.getByRole("heading", { name: "Elige tu plan" }),
  ).toBeVisible();
}

async function cardPositions(cards: Locator) {
  return cards.evaluateAll((items) =>
    items.map((item) => {
      const { x, y, width, height } = item.getBoundingClientRect();
      return { x, y, width, height };
    }),
  );
}

test("T-US02-CR-01/02: live cards reflow, select by touch and pointer, and retain native keyboard behavior", async ({
  page,
}) => {
  await openPlans(page, "co");
  const lane = page
    .getByRole("heading", { name: "Elige tu plan" })
    .locator("xpath=..");
  const cards = page.locator("article");
  await expect(cards).toHaveCount(3);
  await expect(cards.locator("label span")).toHaveText([
    "Esencial",
    "Ruta",
    "Integral",
  ]);

  for (const [viewport, expectedLane, columns] of [
    [320, 280, 1],
    [575, 535, 1],
    [576, 536, 2],
    [855, 815, 2],
    [856, 816, 3],
    [1440, 928, 3],
  ]) {
    await page.setViewportSize({ width: viewport, height: 1000 });
    const laneBox = await lane.boundingBox();
    expect(laneBox?.width).toBe(expectedLane);
    const positions = await cardPositions(cards);
    expect(
      positions.filter(({ y }) => Math.abs(y - positions[0].y) < 1),
    ).toHaveLength(columns);
    expect(
      await page.evaluate(() => document.documentElement.scrollWidth),
    ).toBe(viewport);
  }

  await page.setViewportSize({ width: 1440, height: 1000 });
  const initialPositions = await cardPositions(cards);
  expect(initialPositions.map(({ y }) => Math.round(y))).toEqual([
    Math.round(initialPositions[0].y),
    Math.round(initialPositions[0].y),
    Math.round(initialPositions[0].y),
  ]);

  const essential = page.getByRole("radio", { name: "Esencial", exact: true });
  const route = page.getByRole("radio", { name: "Ruta", exact: true });
  const integral = page.getByRole("radio", { name: "Integral", exact: true });
  const next = page.getByRole("button", { name: "Continuar" });
  await expect(route).toHaveAccessibleDescription(
    /COP.*179\.900,00.*Recomendado/,
  );
  await expect(next).toBeDisabled();

  await essential.click();
  await expect(essential).toBeChecked();
  await page.getByText("Ruta", { exact: true }).click();
  await expect(route).toBeChecked();
  await expect(essential).not.toBeChecked();
  await page.getByText(/COP\s*199\.900,00/).click();
  await expect(integral).toBeChecked();
  await page.getByText("Responsabilidad civil").last().click();
  await expect(route).toBeChecked();
  await page.getByText("Ayuda con batería descargada").last().click();
  await expect(integral).toBeChecked();
  await page.touchscreen.tap(
    (await page.getByText("Orientación telefónica tras un accidente").boundingBox())!
      .x + 5,
    (await page.getByText("Orientación telefónica tras un accidente").boundingBox())!
      .y + 5,
  );
  await expect(essential).toBeChecked();

  const routeCard = await cards.nth(1).boundingBox();
  expect(routeCard).not.toBeNull();
  await page.mouse.click(
    routeCard!.x + routeCard!.width - 4,
    routeCard!.y + routeCard!.height - 4,
  );
  await expect(route).toBeChecked();
  await expect(essential).not.toBeChecked();
  await expect(next).toBeEnabled();
  await expect(page).toHaveURL(/\/co\/quote\/plans$/);
  expect(await cardPositions(cards)).toEqual(initialPositions);

  await page.getByRole("heading", { name: "Elige tu plan" }).focus();
  await page.keyboard.press("Tab");
  await expect(route).toBeFocused();
  await page.keyboard.press("ArrowRight");
  await expect(integral).toBeFocused();
  await expect(integral).toBeChecked();
  await page.keyboard.press("Space");
  await expect(integral).toBeChecked();
  await expect(next).toBeEnabled();

  await page.emulateMedia({ forcedColors: "active" });
  await page.getByRole("heading", { name: "Elige tu plan" }).focus();
  await page.keyboard.press("Tab");
  await expect(integral).toBeFocused();
  await expect(integral).toHaveCSS("outline-style", "solid");
  await page.screenshot({
    path: "/private/tmp/us02-card-revision-live-co.png",
    fullPage: true,
  });

  await openPlans(page, "cl");
  await expect(page.getByRole("radio")).toHaveCount(3);
  await expect(page.getByText(/CLP\s*29\.900/)).toBeVisible();
  for (const width of [320, 1440]) {
    await page.setViewportSize({ width, height: 1000 });
    expect(
      await page.evaluate(() => document.documentElement.scrollWidth),
    ).toBe(width);
    const positions = await cardPositions(page.locator("article"));
    if (width === 1440)
      expect(positions.filter(({ y }) => Math.abs(y - positions[0].y) < 1)).toHaveLength(3);
  }
  await page.screenshot({
    path: "/private/tmp/us02-card-revision-live-cl.png",
    fullPage: true,
  });
});

